Dataspatium.assets.register("presets/api/hav-geodata.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"hav-geodata\",\n  \"name\": \"Havs- och vattenmyndigheten geodata (WFS)\",\n  \"publisher\": \"Havs- och vattenmyndigheten\",\n  \"description\": \"Hav, kust och vatten från HaV: skyddade områden, vattenförekomster, fiske med mera. Välj lager och hämta objekten med geometri.\",\n  \"docs\": \"https://www.havochvatten.se/data-kartor-och-rapporter/kartor-och-gis/geodata.html\",\n  \"license\": {\n    \"name\": \"HaV öppna data\",\n    \"url\": \"https://www.havochvatten.se/data-kartor-och-rapporter/kartor-och-gis/geodata.html\"\n  },\n  \"level\": 1,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://geodata.havochvatten.se/geoservices/ows\",\n  \"auth\": {\n    \"type\": \"none\"\n  },\n  \"family\": {\n    \"type\": \"geodata\",\n    \"kind\": \"wfs\"\n  },\n  \"endpoints\": [],\n  \"notes\": \"Lagren hämtas från tjänsten när källan öppnas (GetCapabilities respektive tjänstekatalogen). Svaren är GeoJSON i WGS 84 och öppnas som kartor.\",\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"Swedish Agency for Marine and Water Management geodata (WFS)\",\n      \"description\": \"Sea, coast and water layers: protected areas, water bodies, fisheries and more. Choose a layer and fetch the features with geometry.\",\n      \"notes\": \"The layers are read from the service when the source is opened (GetCapabilities or the service directory). Answers are GeoJSON in WGS 84 and open as maps.\"\n    },\n    \"da\": {\n      \"name\": \"Havs- och vattenmyndigheten geodata (WFS)\",\n      \"description\": \"Hav, kyst og vand fra HaV: beskyttede områder, vandforekomster, fiskeri med mere. Vælg et lag og hent objekterne med geometri.\",\n      \"notes\": \"Lagene hentes fra tjenesten, når kilden åbnes (GetCapabilities henholdsvis tjenestekataloget). Svarene er GeoJSON i WGS 84 og åbnes som kort.\"\n    },\n    \"nb\": {\n      \"name\": \"Havs- och vattenmyndigheten geodata (WFS)\",\n      \"description\": \"Hav, kyst og vann fra HaV: verneområder, vannforekomster, fiske med mer. Velg et lag og hent objektene med geometri.\",\n      \"notes\": \"Lagene hentes fra tjenesten når kilden åpnes (GetCapabilities respektive tjenestekatalogen). Svarene er GeoJSON i WGS 84 og åpnes som kart.\"\n    },\n    \"fi\": {\n      \"name\": \"Havs- och vattenmyndigheten paikkatieto (WFS)\",\n      \"description\": \"Meri, rannikko ja vedet HaV:lta: suojelualueet, vesimuodostumat, kalastus ja muuta. Valitse taso ja nouda kohteet geometrioineen.\",\n      \"notes\": \"Tasot noudetaan palvelusta, kun lähde avataan (GetCapabilities tai palveluhakemisto). Vastaukset ovat GeoJSONia WGS 84:ssä ja avautuvat karttoina.\"\n    },\n    \"is\": {\n      \"name\": \"Landupplýsingar Havs- och vattenmyndigheten (WFS)\",\n      \"description\": \"Haf, strönd og vatn frá HaV: vernduð svæði, vatnshlot, fiskveiðar og fleira. Veldu lag og sæktu fitjurnar með rúmfræði.\",\n      \"notes\": \"Lögin eru sótt úr þjónustunni þegar uppsprettan er opnuð (GetCapabilities eða þjónustuskráin). Svörin eru GeoJSON í WGS 84 og opnast sem kort.\"\n    }\n  }\n}\n");
